void main() {
  // ── AC1 — draft lifecycle invariant (UT-lifecycle) ──────────────────────
  group('AC1 — every draft-capable create has a failure-path guard', () {
    for (final wf in [
      '.github/workflows/build-macos.yml',
      '.github/workflows/build-mobile.yml',
      '.github/workflows/ci.yml',
